import json,html,shutil
from pathlib import Path
from PIL import Image
out=Path('scratch/proportion-check-root');rows=json.load(open(out/'review-results.json',encoding='utf-8'))
for r in rows:
 p=r['plan'];rects=[q[1:5]for q in p['rooms']+p.get('spaces',[])+p['corridors']+([p['station']]if p.get('station')else[])]+p.get('reviewStationParts',[])
 l=max(0,min(q[0]for q in rects)-20);t=max(0,min(q[1]for q in rects)-20)
 with Image.open(p['image'])as im:
  right=min(im.width,max(q[0]+q[2]for q in rects)+20);bottom=min(im.height,max(q[1]+q[3]for q in rects)+20)
  crop=im.crop((l,t,right,bottom)).convert('RGBA');white=Image.new('RGBA',crop.size,'white');white.alpha_composite(crop);white.convert('RGB').save(out/(r['ward']+'_'+r['floor']+'_source.png'))
 r['sourceCrop']='scratch/proportion-check-root/'+r['ward']+'_'+r['floor']+'_source.png'
 r['overlay']='scratch/proportion-check-root/'+r['ward']+'_'+r['floor']+'_after.png'
 r['sourceScaleNote']='掃描圖像素比例；不是現場實測公尺'
for ward,label in [('14A','14A'),('12PE','兒醫12PE'),('06W3','06W3')]:
 for mode in ['2D','3D']:
  p=Path('D:/Users/006340/Documents/ChatGPT/平面圖/'+label+'_逐原圖比例核對_'+mode+'.png')
  if p.exists():shutil.copyfile(p,out/('preview-'+ward+'-'+mode+'.png'))
(out/'report-data.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2),encoding='utf-8')
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>全部病房原圖比例核對</title><style>body{font:17px "Microsoft JhengHei",sans-serif;margin:24px auto;padding:0 24px;max-width:1600px;color:#203e50;background:#f7f9fb}h1{font-size:28px}p{line-height:1.7}.metrics,.controls{display:flex;gap:16px;flex-wrap:wrap;padding:14px;background:white;border:1px solid #d1dde3;border-radius:10px}.metric{font-weight:bold}select{font:inherit;padding:8px;max-width:100%}.compare{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:white;padding:12px;border:1px solid #d1dde3;border-radius:10px}.card img{width:100%;height:420px;object-fit:contain;object-position:top left;background:white}.warning{border-left:5px solid #cc9127;padding:10px 16px;background:#fff8e9}table{border-collapse:collapse;width:100%;background:white}td,th{padding:9px;border:1px solid #d1dde3;text-align:left;vertical-align:top}a{color:#087baa}button{font:inherit;padding:8px}small{color:#657b88}.notes{white-space:pre-line}.thumbs{display:flex;gap:12px}.thumbs img{width:31%;object-fit:contain}@media(max-width:900px){.compare{grid-template-columns:1fr}.card img{height:auto}} </style><h1>全部病房原圖比例核對</h1><p>逐份原圖核對病室外框、護理站與走道的相對長寬。病室附屬的前室／浴廁帶與原床區分開保存，床位留在原床區。下方疊圖直接使用本次配置資料的來源座標；建築外框的顯示縮放另行處理，未作為原圖比例已正確的證據。</p><div class="metrics"><span class="metric">82 組其他病房配置</span><span class="metric">31 份來源圖</span><span class="metric">738 個病室外框校正</span><span class="metric">48 組護理站分區校正</span><span id="validation">空間重疊／走道穿越／床位進入新增附屬區：0</span></div><p><small>82組包含5W2的2F／5F兩個展示入口；04W2後續人工調整保留。東址1、2、10樓依指定排除，兒醫14樓維持既有排除狀態。弧角、斜角與小凹角仍為內接近似，並非施工圖或實測尺寸。</small></p><p class="warning">15C 原圖此處標為護理長室／會談及未命名空間，不能據此核實封閉護理站；已撤回原合併方塊並保留待核實紀錄。另已看過6E1原圖，但現有單位／床號資料未列06E1，本次沒有推算新增現行病房或床號。</p><div class="controls"><label>院區 <select id="campus"><option value="all">全部</option><option value="east">東址</option><option value="west">西址</option><option value="child">兒醫</option></select></label><label>病房 <select id="ward"></select></label><a id="pdf" target="_blank">開啟原始PDF</a><a href="全部病房圖面檢查.html" target="_blank">開啟互動2D／3D圖面</a></div><h2 id="title"></h2><p id="summary"></p><div class="compare"><section class="card"><h3>原圖局部</h3><a id="sourceLink" target="_blank"><img id="source" alt="病房原圖局部"></a></section><section class="card"><h3>本次配置與原圖疊合</h3><a id="overlayLink" target="_blank"><img id="overlay" alt="校正後配置疊合原圖"></a></section></div><p><small>紅：病室完整外框；棕：保留的床區；青：護理站；紫：其他空間；黃：走道。點圖可開啟原尺寸核對。</small></p><p id="notes" class="notes"></p><h2>逐病房紀錄</h2><p>點選病房名稱可切換上方原圖與疊圖。</p><table><thead><tr><th>院區／樓層／病房</th><th>病室</th><th>護理站</th><th>原圖</th></tr></thead><tbody id="rows"></tbody></table><h2>實際畫面範例</h2><div class="thumbs"><a href="scratch/proportion-check-root/preview-14A-2D.png"><img src="scratch/proportion-check-root/preview-14A-2D.png" alt="東址14A"></a><a href="scratch/proportion-check-root/preview-12PE-2D.png"><img src="scratch/proportion-check-root/preview-12PE-2D.png" alt="兒醫12PE"></a><a href="scratch/proportion-check-root/preview-06W3-2D.png"><img src="scratch/proportion-check-root/preview-06W3-2D.png" alt="西址06W3"></a></div><script>
const data=__DATA__,byId=id=>document.getElementById(id),site=r=>r.building==='E01_MAIN'?'east':r.building==='CHILD_HOSPITAL'?'child':'west',siteName=r=>({east:'東址',west:'西址',child:'兒醫'})[site(r)];
const select=byId('ward');function show(){const r=data[Number(select.value)],p=r.plan;byId('title').textContent=siteName(r)+' '+r.floor+' '+r.ward;byId('summary').textContent=r.roomCheck+'；護理站：'+r.stationCheck;byId('pdf').href=encodeURI(r.source);byId('source').src=r.sourceCrop;byId('sourceLink').href=r.sourceCrop;byId('overlay').src=r.overlay;byId('overlayLink').href=r.overlay;byId('notes').textContent=p.notes.join('\\n')+'\\n'+r.corridorCheck+'。原床號與未定位資料保留；示意床不代表已核實的床數。';}
function filter(wanted){select.replaceChildren();data.forEach((r,i)=>{if(byId('campus').value!=='all'&&site(r)!==byId('campus').value)return;const o=document.createElement('option');o.value=i;o.textContent=siteName(r)+' / '+r.floor+' / '+r.ward;select.append(o);});if(wanted!=null&&[...select.options].some(o=>o.value==wanted))select.value=wanted;show();}
byId('campus').onchange=()=>filter();select.onchange=show;const body=byId('rows');data.forEach((r,i)=>{const tr=document.createElement('tr');for(const text of[siteName(r)+' '+r.floor+' '+r.ward,'原圖病室 '+r.plan.rooms.length+' 個；本次校正外框 '+r.roomEnvelopes+' 個',r.stationCheck,r.source]){const td=document.createElement('td');td.textContent=text;tr.append(td);}const link=document.createElement('a');link.href='#title';link.textContent=tr.children[0].textContent;link.onclick=()=>{byId('campus').value='all';filter(i);};tr.children[0].replaceChildren(link);const pdf=document.createElement('a');pdf.href=encodeURI(r.source);pdf.target='_blank';pdf.textContent=r.source;tr.children[3].replaceChildren(pdf);body.append(tr);});filter(data.findIndex(r=>r.ward==='14A'));
</script></html>'''
page=page.replace('__DATA__',json.dumps(rows,ensure_ascii=False,separators=(',',':')))
Path('全部病房原圖比例核對.html').write_text(page,encoding='utf-8')
print('report entries',len(rows),'missing overlay',sum(not Path(r['overlay']).exists()for r in rows))
